/* ================= HERO FIELD: the firm's own photograph. "Touro" is Portuguese for bull, and tourocp.com carries a
   professional studio portrait of a black Iberian fighting bull, lit from one side against black. DG: when the original
   has real professional photography, use it, graded, rather than an illustration. The portrait is set full-bleed on the
   right (top band on phones, clear of the text: CW), graded warm-neutral to the charcoal palette, with a slow breathing
   push-in, a soft key light that drifts across the horns, dust motes in that light, film grain and a scrim on the text
   side. It moves on its own, so no pointer response (CZ). ================= */
var BULL="data:image/webp;base64,";
var field=(function(){
  var cv=$("#field"),c=cv.getContext("2d"),dpr=1,w=0,h=0,running=false,raf=0,t0=performance.now(),shown=false,lastF=0;
  var IN={v:1},dim=1,dimT=1,SP={v:0},G=null,img=new Image(),ok=false,oGrain=null,oPh=null,MOTE=[];
  function rng(s){return function(){s=(s*16807)%2147483647;return (s-1)/2147483646}}
  function sm(x){x=x<0?0:x>1?1:x;return x*x*(3-2*x)}
  img.onload=function(){ok=true;if(w)build();if(!running)frame(true)};img.src=BULL;
  function geo(){
    var side=Math.max(Math.min(72,Math.max(16,w*.042)),(w-1320)/2),cw=w-2*side,mob=w<861;
    /* the portrait box: desktop, the right ~58% at full height; phones, a band at the top above the title */
    var ar=1571/1500,bh,bw,bx,by;
    if(mob){var band=Math.max(230,h*.34);bh=Math.min((band-78)/.62,w*1.1*ar);bw=bh/ar;bx=(w-bw)/2;by=78-bh*.11}
    else{bh=h*1.12;bw=bh/ar;bx=Math.max(side+cw*.36,w-bw*.94);by=-h*.03}
    return {mob:mob,side:side,cw:cw,bx:bx,by:by,bw:bw,bh:bh,band:mob?Math.max(230,h*.34):h};
  }
  function mk(W,H){var o=document.createElement("canvas");o.width=Math.max(1,Math.round(W*dpr));o.height=Math.max(1,Math.round(H*dpr));var g=o.getContext("2d");g.setTransform(dpr,0,0,dpr,0,0);return [o,g]}
  function build(){
    /* grain tile */
    var A=mk(w,h),g=A[1];oGrain=A[0];var R=rng(7),id=g.createImageData(Math.round(w*dpr),Math.round(h*dpr)),d=id.data;
    for(var i=0;i<d.length;i+=4){var v=R()*255|0;d[i]=d[i+1]=d[i+2]=v;d[i+3]=R()<.5?9:0}g.putImageData(id,0,0);
    if(!ok)return;
    /* the graded portrait, once: edges feathered into the black so the frame never shows (CV) */
    var P=mk(G.bw,G.bh),p=P[1];oPh=P[0];
    p.drawImage(img,0,0,G.bw,G.bh);
    p.globalCompositeOperation="multiply";p.fillStyle="rgb(246,238,226)";p.fillRect(0,0,G.bw,G.bh);
    p.globalCompositeOperation="destination-in";
    var rg=p.createRadialGradient(G.bw*.5,G.bh*.36,0,G.bw*.5,G.bh*.42,G.bw*.62);rg.addColorStop(0,"rgba(0,0,0,1)");rg.addColorStop(.72,"rgba(0,0,0,1)");rg.addColorStop(1,"rgba(0,0,0,0)");
    p.fillStyle=rg;p.fillRect(0,0,G.bw,G.bh);p.globalCompositeOperation="source-over";
    var Rm=rng(31);MOTE=[];for(var m=0;m<(G.mob?34:70);m++)MOTE.push([Rm(),Rm(),.4+Rm()*1.3,Rm()*6.28,.2+Rm()*.8]);
  }
  function size(){dpr=Math.min(window.devicePixelRatio||1,2);w=document.documentElement.clientWidth||innerWidth;h=innerHeight;cv.width=Math.round(w*dpr);cv.height=Math.round(h*dpr);G=geo();build();if(!running)frame(true)}
  function frame(once){
    var now=performance.now();
    if(!once&&running&&now-lastF<31){raf=requestAnimationFrame(function(){frame(false)});return}lastF=now;
    var t=RM?9:(now-t0)/1000;dim+=(dimT-dim)*.08;
    var e=sm(IN.v);cv.style.opacity=shown?String(.5+.5*dim):"";
    c.setTransform(dpr,0,0,dpr,0,0);c.globalAlpha=1;c.fillStyle="#050505";c.fillRect(0,0,w,h);
    if(oPh){
      /* slow breathing push-in, and the intro: the bull rises out of the dark */
      var z=1.02+.025*Math.sin(t*.16)+(1-e)*.05,cx=G.bx+G.bw*.5,cy=G.by+G.bh*.38,dy=G.mob?0:-SP.v*h*.05;
      c.save();c.globalAlpha=e;c.translate(cx,cy+dy);c.scale(z,z);c.drawImage(oPh,-G.bw*.5,-G.bh*.38,G.bw,G.bh);c.restore();
      /* a soft key light drifting across the horns */
      var lx=cx+G.bw*(.18*Math.sin(t*.11)),ly=G.by+G.bh*.24+dy;
      c.globalCompositeOperation="soft-light";c.globalAlpha=e*.55;
      var kg=c.createRadialGradient(lx,ly,0,lx,ly,G.bw*.42);kg.addColorStop(0,"rgba(255,236,206,.9)");kg.addColorStop(1,"rgba(255,236,206,0)");c.fillStyle=kg;c.fillRect(0,0,w,h);
      c.globalCompositeOperation="source-over";
      /* dust in the light */
      c.fillStyle="rgba(240,226,200,1)";
      for(var i=0;i<MOTE.length;i++){var M=MOTE[i],mx=G.bx+G.bw*(.1+.8*((M[0]+t*.004*M[4])%1)),my=G.by+G.bh*(.08+.62*((M[1]+t*.006*M[4])%1))+Math.sin(t*.5+M[3])*6+dy;
        var near=Math.max(0,1-Math.hypot(mx-lx,my-ly)/(G.bw*.45));if(near<=0)continue;c.globalAlpha=e*near*.55*(.5+.5*Math.sin(t*.8+M[3]));c.beginPath();c.arc(mx,my,M[2],0,6.283);c.fill()}
    }
    c.globalAlpha=e*.9;c.drawImage(oGrain,0,0,w,h);c.globalAlpha=1;
    if(!G.mob){var lv=c.createLinearGradient(0,0,G.side+G.cw*.6,0);lv.addColorStop(0,"rgba(5,5,5,.86)");lv.addColorStop(.6,"rgba(5,5,5,.45)");lv.addColorStop(1,"rgba(5,5,5,0)");c.fillStyle=lv;c.fillRect(0,0,w,h);
      var bv=c.createLinearGradient(0,h*.74,0,h);bv.addColorStop(0,"rgba(5,5,5,0)");bv.addColorStop(1,"rgba(5,5,5,.7)");c.fillStyle=bv;c.fillRect(0,h*.74,w,h*.26)}
    else{var fb=G.band,mg=c.createLinearGradient(0,fb*.7,0,fb);mg.addColorStop(0,"rgba(5,5,5,0)");mg.addColorStop(1,"rgba(5,5,5,1)");c.fillStyle=mg;c.fillRect(0,fb*.7,w,fb*.3);c.fillStyle="#050505";c.fillRect(0,fb,w,h-fb)}
    if(!shown&&oPh){shown=true;requestAnimationFrame(function(){requestAnimationFrame(function(){cv.classList.add("ready")})})}
    if(!once&&running)raf=requestAnimationFrame(function(){frame(false)});
  }
  function start(){if(running||document.hidden)return;running=true;raf=requestAnimationFrame(function(){frame(false)})}
  function stop(){running=false;cancelAnimationFrame(raf)}
  var rzT;addEventListener("resize",function(){clearTimeout(rzT);rzT=setTimeout(size,120)});size();
  return {start:start,stop:stop,once:function(){frame(true)},setScroll:function(p){SP.v=Math.round(p*40)/40},
    intro:function(d){if(RM){IN.v=1;return}IN.v=0;gsap.to(IN,{v:1,duration:d,ease:"power2.out"})},setDim:function(d){dimT=d},snapDim:function(d){dim=dimT=d},running:function(){return running},focus:function(){return G?[G.bx+G.bw*.5,G.by+G.bh*.3]:[w/2,h/2]}};
})();
